1380	<script>
1381	// === track.js — Racing Game ===
1382	// Procedural track generation and rendering for the racing game.
1383	// Manages track data, position queries, collision detection, sky, and road rendering.
1384	// All functions attach to window.R. Assumes R.CONFIG, R.canvas, R.ctx,
1385	// R.camera, R.state, and R.track already exist.
1386	
1387	/* ==========================================================================
1388	   CONFIG defaults — merged into R.CONFIG if keys are missing
1389	   ========================================================================== */
1390	(function ensureTrackConfig() {
1391	  'use strict';
1392	
1393	  window.R = window.R || {};
1394	  window.R.CONFIG = window.R.CONFIG || {};
1395	
1396	  var defaults = {
1397	    // ── Track generation ────────────────────────────────────────────────
1398	    TRACK_CONTROL_POINTS:   14,       // number of spline control points
1399	    TRACK_SEGMENTS_PER_CP:  15,       // segments between each control-point pair
1400	    TRACK_BASE_RADIUS:      1350,     // base circle radius for control points
1401	    TRACK_RADIUS_VAR1:      480,      // amplitude of primary oval harmonic
1402	    TRACK_RADIUS_VAR2:      280,      // amplitude of triangular harmonic
1403	    TRACK_RADIUS_VAR3:      140,      // amplitude of fine-detail harmonic
1404	    TRACK_RADIUS_JITTER:    120,      // max random offset per control point
1405	    TRACK_TOTAL_LENGTH:     9000,     // approximate target (actual is computed)
1406	
1407	    // ── Road geometry ───────────────────────────────────────────────────
1408	    ROAD_WIDTH:             180,
1409	    ROAD_WIDTH_MIN:         130,      // narrowest on tight hairpins
1410	    ROAD_SHOULDER:          20,       // extra width for rumble strips / curbs
1411	    RUMBLE_WIDTH:           6,
1412	    RUMBLE_COLOR_A:         '#ff0000', // curb stripe A (red)
1413	    RUMBLE_COLOR_B:         '#ffffff', // curb stripe B (white)
1414	    CURB_CURVATURE_THRESH:  0.0012,   // |curvature| above this → draw curbs
1415	
1416	    // ── Lane markings ───────────────────────────────────────────────────
1417	    LANE_MARKER_DASH:       40,       // world units — dash length
1418	    LANE_MARKER_GAP:        30,       // world units — gap between dashes
1419	    LANE_MARKER_COLOR:      '#ccc',
1420	    LANE_MARKER_WIDTH:      1.5,
1421	
1422	    // ── Elevation / hills ───────────────────────────────────────────────
1423	    HILL_AMPLITUDE_A:       28,       // primary hill height
1424	    HILL_FREQ_A:            0.0012,   // primary hill frequency (rad / world-unit)
1425	    HILL_AMPLITUDE_B:       14,       // secondary hill height
1426	    HILL_FREQ_B:            0.0030,   // secondary hill frequency
1427	    HILL_PHASE_B:           1.7,      // phase offset for secondary hills
1428	
1429	    // ── Rendering ───────────────────────────────────────────────────────
1430	    RENDER_DISTANCE:        1200,     // world units — max segment distance from camera to draw
1431	    RENDER_FADE_NEAR:       1000,     // world units — start fading segments
1432	    HORIZON_Y:              200,      // screen-space Y of horizon line
1433	    PERSPECTIVE_COEFF:      0.0022,   // perspective strength (higher = more depth)
1434	    ROAD_V_OFFSET:          0.42,     // forward→screen-Y slope multiplier
1435	    SEGMENT_COLOR_VAR:      4,        // ± brightness variation per segment
1436	    TRACK_BG_COLOR:         '#3a5a2c',// grass / terrain color behind the road
1437	    TRACK_BG_COLOR_FAR:     '#4a6a3c',// grass color near horizon (atmospheric)
1438	    SHOULDER_COLOR:         '#8b4513',// dirt shoulder color
1439	
1440	    // ── Fog ─────────────────────────────────────────────────────────────
1441	    FOG_NEAR:               300,
1442	    FOG_FAR:                800,
1443	    FOG_COLOR:              '#87CEEB',
1444	
1445	    // ── Scenery (used by scenery module, defaults here for self-containment)
1446	    SCENERY_OBJECTS:        80,
1447	    SCENERY_LATERAL_MIN:    0.3,
1448	    SCENERY_LATERAL_MAX:    1.2,
1449	  };
1450	
1451	  for (var k in defaults) {
1452	    if (!(k in R.CONFIG)) R.CONFIG[k] = defaults[k];
1453	  }
1454	})();
1455	
1456	/* ==========================================================================
1457	   PRIVATE HELPERS — not attached to R; file-scoped
1458	   ========================================================================== */
1459	
1460	/**
1461	 * Normalise an angle to the range [-PI, PI].
1462	 * @param {number} a Angle in radians
1463	 * @returns {number} Normalised angle
1464	 */
1465	function _normAngle(a) {
1466	  while (a >  Math.PI) a -= Math.PI * 2;
1467	  while (a < -Math.PI) a += Math.PI * 2;
1468	  return a;
1469	}
1470	
1471	/**
1472	 * Catmull-Rom spline interpolation between four 2D control points.
1473	 * Produces a smooth curve passing through p1 and p2, guided by p0 and p3.
1474	 * @param {{x:number,z:number}} p0 Previous control point
1475	 * @param {{x:number,z:number}} p1 Start control point
1476	 * @param {{x:number,z:number}} p2 End control point
1477	 * @param {{x:number,z:number}} p3 Next control point
1478	 * @param {number} t Interpolation factor [0, 1]
1479	 * @returns {{x:number,z:number}} Interpolated point
1480	 */
1481	function _catmullRom(p0, p1, p2, p3, t) {
1482	  var t2 = t * t;
1483	  var t3 = t2 * t;
1484	  return {
1485	    x: 0.5 * (
1486	      (2 * p1.x) +
1487	      (-p0.x + p2.x) * t +
1488	      (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
1489	      (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
1490	    ),
1491	    z: 0.5 * (
1492	      (2 * p1.z) +
1493	      (-p0.z + p2.z) * t +
1494	      (2 * p0.z - 5 * p1.z + 4 * p2.z - p3.z) * t2 +
1495	      (-p0.z + 3 * p1.z - 3 * p2.z + p3.z) * t3
1496	    )
1497	  };
1498	}
1499	
1500	/**
1501	 * Direction angle (radians) from point a to point b in the XZ plane.
1502	 * Angle 0 = +Z direction; increases clockwise when viewed from above (+Y).
1503	 * @param {{x:number,z:number}} a
1504	 * @param {{x:number,z:number}} b
1505	 * @returns {number} Angle in radians
1506	 */
1507	function _angleTo(a, b) {
1508	  return Math.atan2(b.x - a.x, b.z - a.z);
1509	}
1510	
1511	/**
1512	 * Euclidean distance between two 2D points in XZ space.
1513	 * @param {{x:number,z:number}} a
1514	 * @param {{x:number,z:number}} b
1515	 * @returns {number}
1516	 */
1517	function _distXZ(a, b) {
1518	  var dx = a.x - b.x;
1519	  var dz = a.z - b.z;
1520	  return Math.sqrt(dx * dx + dz * dz);
1521	}
1522	
1523	/**
1524	 * Compute forward distance from camera to a segment, handling the closed-loop
1525	 * wrap so that the shorter arc is always used.
1526	 * @param {number} segDist Cumulative distance of the segment
1527	 * @param {number} camDist Camera's cumulative track distance
1528	 * @param {number} totalLen Total track length
1529	 * @returns {number} Signed forward distance (positive = ahead, negative = behind)
1530	 */
1531	function _forwardDist(segDist, camDist, totalLen) {
1532	  var dz = segDist - camDist;
1533	  if (dz >  totalLen / 2) dz -= totalLen;
1534	  if (dz < -totalLen / 2) dz += totalLen;
1535	  return dz;
1536	}
1537	
1538	/* ==========================================================================
1539	   R.initTrack() — Generate a closed-loop racing circuit
1540	   ========================================================================== */
1541	
1542	/**
1543	 * Generates a closed-loop racing track using Catmull-Rom spline interpolation
1544	 * through stochastically-placed control points on a distorted circle.
1545	 *
1546	 * Each segment stores:
1547	 *   { worldX, worldY, worldZ, width, curvature, elevation, type, dist, angle }
1548	 *
1549	 * After generation populates:
1550	 *   R.track.segments[], R.track.totalLength, R.track.startX, R.track.startZ,
1551	 *   R.track.startAngle
1552	 */
1553	R.initTrack = function () {
1554	  var cfg  = R.CONFIG;
1555	  var nCP  = cfg.TRACK_CONTROL_POINTS;
1556	  var nSeg = cfg.TRACK_SEGMENTS_PER_CP;
1557	
1558	  // ── Step 1: Generate control points on a distorted circle ───────────
1559	  var cps = [];
1560	  var baseR = cfg.TRACK_BASE_RADIUS;
1561	  for (var i = 0; i < nCP; i++) {
1562	    var angle = (i / nCP) * Math.PI * 2;
1563	    var r = baseR
1564	          + Math.sin(angle * 2) * cfg.TRACK_RADIUS_VAR1
1565	          + Math.cos(angle * 3) * cfg.TRACK_RADIUS_VAR2
1566	          + Math.sin(angle * 5) * cfg.TRACK_RADIUS_VAR3;
1567	    // Random jitter (use seed if provided, otherwise Math.random)
1568	    var jitter = cfg.TRACK_SEED != null
1569	      ? (_pseudoRandom(i) - 0.5) * cfg.TRACK_RADIUS_JITTER * 2
1570	      : (Math.random() - 0.5) * cfg.TRACK_RADIUS_JITTER * 2;
1571	    // Apply jitter proportionally so the shape doesn't self-intersect
1572	    var rFinal = r + jitter;
1573	    if (rFinal < 300) rFinal = 300; // prevent collapsing to centre
1574	    cps.push({ x: Math.cos(angle) * rFinal, z: Math.sin(angle) * rFinal });
1575	  }
1576	
1577	  // ── Step 2: Interpolate segments via Catmull-Rom ────────────────────
1578	  var samples  = []; // intermediate dense samples {x, z}
1579	  var totalCP  = cps.length;
1580	  for (var ci = 0; ci < totalCP; ci++) {
1581	    var p0 = cps[(ci - 1 + totalCP) % totalCP];
1582	    var p1 = cps[ci];
1583	    var p2 = cps[(ci + 1) % totalCP];
1584	    var p3 = cps[(ci + 2) % totalCP];
1585	    for (var si = 0; si < nSeg; si++) {
1586	      var t = si / nSeg;
1587	      var pt = _catmullRom(p0, p1, p2, p3, t);
1588	      samples.push(pt);
1589	    }
1590	  }
1591	
1592	  // ── Step 3: Build segment objects ───────────────────────────────────
1593	  var segs    = [];
1594	  var nSamples = samples.length;
1595	  // Temporaries for curvature calculation
1596	  var angles  = new Array(nSamples);
1597	  var segDists = new Array(nSamples); // Euclidean distance between consecutive samples
1598	
1599	  // First pass: compute angles and segment lengths (distance between consecutive samples)
1600	  for (var s = 0; s < nSamples; s++) {
1601	    var curr  = samples[s];
1602	    var next  = samples[(s + 1) % nSamples];
1603	    var prev  = samples[(s - 1 + nSamples) % nSamples];
1604	    segDists[s] = _distXZ(curr, next);
1605	    // Smooth angle using central difference (wrapping)
1606	    var anglePrev = _angleTo(prev, curr);
1607	    var angleNext = _angleTo(curr, next);
1608	    // Average the two half-angles for a smoother direction at this point
1609	    angles[s] = _normAngle((anglePrev + angleNext) / 2);
1610	  }
1611	
1612	  // Compute curvature as angle change per unit distance
1613	  var curvatures = new Array(nSamples);
1614	  // Find maximum absolute curvature for width-ramping
1615	  var maxAbsCurv = 0;
1616	  for (var s2 = 0; s2 < nSamples; s2++) {
1617	    var aCurr  = angles[s2];
1618	    var aNext  = angles[(s2 + 1) % nSamples];
1619	    var deltaA = _normAngle(aNext - aCurr);
1620	    var d      = segDists[s2];
1621	    curvatures[s2] = d > 0.01 ? deltaA / d : 0;
1622	    var ac = Math.abs(curvatures[s2]);
1623	    if (ac > maxAbsCurv) maxAbsCurv = ac;
1624	  }
1625	  // Guard against zero max curvature (perfect circle)
1626	  if (maxAbsCurv < 0.0001) maxAbsCurv = 0.0001;
1627	
1628	  // Cumulative distance
1629	  var cumDist = 0;
1630	  for (var s3 = 0; s3 < nSamples; s3++) {
1631	    var absCurv      = Math.abs(curvatures[s3]);
1632	    var widthFraction = absCurv / maxAbsCurv; // 0 on straights, 1 on tightest curve
1633	    if (widthFraction > 1) widthFraction = 1;
1634	
1635	    var roadW = cfg.ROAD_WIDTH + (cfg.ROAD_WIDTH_MIN - cfg.ROAD_WIDTH) * widthFraction;
1636	
1637	    // Classification
1638	    var stype = 'straight';
1639	    if (absCurv > maxAbsCurv * 0.15) stype = 'curve';
1640	    if (absCurv > maxAbsCurv * 0.55) stype = 'tight_curve';
1641	
1642	    // Elevation
1643	    var d   = cumDist;
1644	    var elev = Math.sin(d * cfg.HILL_FREQ_A)          * cfg.HILL_AMPLITUDE_A
1645	             + Math.sin(d * cfg.HILL_FREQ_B + cfg.HILL_PHASE_B) * cfg.HILL_AMPLITUDE_B;
1646	
1647	    // Check for hill
1648	    if (cfg.HILL_AMPLITUDE_A > 0 || cfg.HILL_AMPLITUDE_B > 0) {
1649	      var nextD  = cumDist + segDists[s3];
1650	      var nextEl = Math.sin(nextD * cfg.HILL_FREQ_A)          * cfg.HILL_AMPLITUDE_A
1651	                 + Math.sin(nextD * cfg.HILL_FREQ_B + cfg.HILL_PHASE_B) * cfg.HILL_AMPLITUDE_B;
1652	      if (Math.abs(nextEl - elev) / Math.max(segDists[s3], 1) > 0.015) {
1653	        stype = 'hill';
1654	      }
1655	    }
1656	
1657	    segs.push({
1658	      worldX:    samples[s3].x,
1659	      worldY:    elev,
1660	      worldZ:    samples[s3].z,
1661	      width:     roadW,
1662	      curvature: curvatures[s3],
1663	      elevation: elev,
1664	      type:      stype,
1665	      dist:      cumDist,
1666	      angle:     angles[s3],
1667	      segDist:   segDists[s3]  // distance to next segment
1668	    });
1669	
1670	    cumDist += segDists[s3];
1671	  }
1672	
1673	  // ── Step 4: Store to R.track ────────────────────────────────────────
1674	  R.track = {
1675	    segments:    segs,
1676	    totalLaps:   cfg.TOTAL_LAPS,
1677	    totalLength: cumDist,
1678	    startX:      segs[0].worldX,
1679	    startY:      segs[0].worldY,
1680	    startZ:      segs[0].worldZ,
1681	    startAngle:  segs[0].angle,
1682	    checkpointCount: cfg.LAP_CHECKPOINT_COUNT || 4
1683	  };
1684	
1685	  // Distribute checkpoints evenly
1686	  R.track.checkpoints = [];
1687	  var cpCount = R.track.checkpointCount;
1688	  for (var c = 0; c < cpCount; c++) {
1689	    var cpDist = (c / cpCount) * R.track.totalLength;
1690	    var cpPos  = R.getTrackPosition(cpDist);
1691	    R.track.checkpoints.push({
1692	      dist: cpDist,
1693	      x:    cpPos.x,
1694	      z:    cpPos.z,
1695	      width: cpPos.width
1696	    });
1697	  }
1698	
1699	  // ── Step 5: Ensure camera Z is initialised ──────────────────────────
1700	  if (R.camera) {
1701	    R.camera.worldZ = segs[0].worldZ;
1702	    R.camera.trackDist = 0;
1703	  }
1704	};
1705	
1706	/**
1707	 * Simple deterministic pseudo-random generator for seeded tracks.
1708	 * Returns a value in [0, 1) based on index.
1709	 * @param {number} idx Integer index
1710	 * @returns {number} Pseudo-random value
1711	 */
1712	function _pseudoRandom(idx) {
1713	  var x = Math.sin(idx * 127.1 + 311.7) * 43758.5453;
1714	  return x - Math.floor(x);
1715	}
1716	
1717	/* ==========================================================================
1718	   R.getTrackPosition(worldZ) — Interpolated position lookup by distance
1719	   ========================================================================== */
1720	
1721	/**
1722	 * Given a cumulative distance along the track, returns the interpolated
1723	 * position and properties at that point. Wraps around for closed circuit.
1724	 *
1725	 * @param {number} dist Cumulative distance (wraps modulo totalLength)
1726	 * @returns {{x:number, y:number, z:number, angle:number, curvature:number, width:number, dist:number, index:number}}
1727	 */
1728	R.getTrackPosition = function (dist) {
1729	  var segs   = R.track.segments;
1730	  var total  = R.track.totalLength;
1731	  var n      = segs.length;
1732	
1733	  // Wrap distance
1734	  var d = dist % total;
1735	  if (d < 0) d += total;
1736	
1737	  // Binary search for the segment just before d
1738	  var lo = 0;
1739	  var hi = n - 1;
1740	  while (lo < hi) {
1741	    var mid = (lo + hi + 1) >> 1;
1742	    if (segs[mid].dist <= d) {
1743	      lo = mid;
1744	    } else {
1745	      hi = mid - 1;
1746	    }
1747	  }
1748	
1749	  var idx = lo;
1750	  var seg = segs[idx];
1751	  var nextIdx = (idx + 1) % n;
1752	  var nextSeg = segs[nextIdx];
1753	
1754	  // Handle wrap: the next segment's dist may be less than current if we wrapped
1755	  var segEndDist = nextSeg.dist;
1756	  if (segEndDist <= seg.dist) segEndDist += total; // wrapped
1757	
1758	  var t = 0;
1759	  var span = segEndDist - seg.dist;
1760	  if (span > 0.0001) {
1761	    var localD = d;
1762	    if (localD < seg.dist) localD += total;
1763	    t = (localD - seg.dist) / span;
1764	  }
1765	  if (t < 0) t = 0;
1766	  if (t > 1) t = 1;
1767	
1768	  return {
1769	    x:          R.lerp(seg.worldX, nextSeg.worldX, t),
1770	    y:          R.lerp(seg.worldY, nextSeg.worldY, t),
1771	    z:          R.lerp(seg.worldZ, nextSeg.worldZ, t),
1772	    angle:      _normAngle(R.lerp(seg.angle, nextSeg.angle, t)),
1773	    curvature:  R.lerp(seg.curvature, nextSeg.curvature, t),
1774	    width:      R.lerp(seg.width, nextSeg.width, t),
1775	    dist:       d,
1776	    index:      idx
1777	  };
1778	};
1779	
1780	/* ==========================================================================
1781	   R.isOnTrack(worldX, worldZ) — Collision detection
1782	   ========================================================================== */
1783	
1784	/**
1785	 * Checks whether a given world position (X, Z) is on the track surface.
1786	 * Finds the nearest segment by track distance, computes lateral offset
1787	 * from the road centre-line, and compares to the segment's half-width.
1788	 *
1789	 * @param {number} wx World X coordinate to test
1790	 * @param {number} wz World Z coordinate to test
1791	 * @returns {{onTrack:boolean, distFromCenter:number, segmentIndex:number, halfWidth:number}}
1792	 */
1793	R.isOnTrack = function (wx, wz) {
1794	  var segs  = R.track.segments;
1795	  var n     = segs.length;
1796	  var total = R.track.totalLength;
1797	
1798	  // Spiral search: start from last known nearest segment and expand outward
1799	  // Fall back to full scan on first call
1800	  var bestIdx    = -1;
1801	  var bestDist2  = Infinity;
1802	
1803	  // Scan all segments — 200-240 is cheap enough per call
1804	  for (var i = 0; i < n; i++) {
1805	    var seg = segs[i];
1806	    var dx  = seg.worldX - wx;
1807	    var dz  = seg.worldZ - wz;
1808	    var d2  = dx * dx + dz * dz;
1809	    if (d2 < bestDist2) {
1810	      bestDist2 = d2;
1811	      bestIdx   = i;
1812	    }
1813	  }
1814	
1815	  if (bestIdx < 0) {
1816	    return { onTrack: false, distFromCenter: Infinity, segmentIndex: -1, halfWidth: 0 };
1817	  }
1818	
1819	  var seg       = segs[bestIdx];
1820	  var segAngle  = seg.angle;
1821	
1822	  // Compute lateral (perpendicular) distance from road centre-line
1823	  // Vector from segment centre to test point
1824	  var dx = wx - seg.worldX;
1825	  var dz = wz - seg.worldZ;
1826	  // Project onto perpendicular direction: left = (cos(angle), -sin(angle))
1827	  var lateralDist = dx * Math.cos(segAngle) - dz * Math.sin(segAngle);
1828	  // Take absolute value for distance from centre
1829	  var absLat = Math.abs(lateralDist);
1830	  var halfW  = seg.width / 2;
1831	
1832	  return {
1833	    onTrack:        absLat <= halfW,
1834	    distFromCenter: absLat,
1835	    segmentIndex:   bestIdx,
1836	    halfWidth:      halfW
1837	  };
1838	};
1839	
1840	/* ==========================================================================
1841	   R.worldToScreen(wx, wy, wz) — World-to-screen projection
1842	   ========================================================================== */
1843	
1844	/**
1845	 * Converts world coordinates to screen coordinates using perspective projection.
1846	 * wz controls depth-based scaling: larger wz = farther away = smaller on screen.
1847	 *
1848	 * The camera position (R.camera.x, R.camera.y) defines the screen centre.
1849	 * If R.camera.worldZ is set, wz is treated as relative to the camera's Z
1850	 * (for proper perspective during racing). Otherwise wz is used as-is.
1851	 *
1852	 * @param {number} wx World X coordinate
1853	 * @param {number} wy World Y coordinate (elevation)
1854	 * @param {number} wz World Z coordinate (depth / forward distance)
1855	 * @returns {{x:number, y:number, scale:number}}
1856	 */
1857	R.worldToScreen=function(wx,wy,wz){var cam=R.camera;if(!cam)return{x:wx,y:wy,scale:1};var zoom=cam.zoom||1;var sx=R.CONFIG.CANVAS_WIDTH/2+(wx-(cam.x||0))*zoom;var sy=R.CONFIG.CANVAS_HEIGHT/2+(wy-(cam.y||0))*zoom;return{x:sx,y:sy,scale:zoom};};
1858	
1859	/* ==========================================================================
1860	   R.renderSky(ctx) — Sky gradient and horizon
1861	   ========================================================================== */
1862	
1863	/**
1864	 * Draws a full-screen sky gradient from a darker top colour to a lighter
1865	 * horizon colour, followed by a narrow ground/horizon strip.
1866	 *
1867	 * Operates in screen space: saves the current transform, resets to identity,
1868	 * draws the sky, and restores.
1869	 *
1870	 * @param {CanvasRenderingContext2D} ctx
1871	 */
1872	R.renderSky = function (ctx) {
1873	  var W = R.CONFIG.CANVAS_WIDTH;
1874	  var H = R.CONFIG.CANVAS_HEIGHT;
1875	  var horizonY = R.CONFIG.HORIZON_Y || 200;
1876	
1877	  ctx.save();
1878	  ctx.setTransform(1, 0, 0, 1, 0, 0);
1879	
1880	  // ── Sky gradient ─────────────────────────────────────────────────────
1881	  var skyTop    = R.CONFIG.SKY_TOP_COLOR    || '#1a1a2e';
1882	  var skyBottom = R.CONFIG.SKY_BOTTOM_COLOR || '#87CEEB';
1883	  var grad = ctx.createLinearGradient(0, 0, 0, horizonY + 40);
