1885	  grad.addColorStop(0.65, '#4a6fa5');
1886	  grad.addColorStop(1,    skyBottom);
1887	  ctx.fillStyle = grad;
1888	  ctx.fillRect(0, 0, W, horizonY + 40);
1889	
1890	  // ── Horizon glow ─────────────────────────────────────────────────────
1891	  var glowGrad = ctx.createLinearGradient(0, horizonY - 20, 0, horizonY + 40);
1892	  glowGrad.addColorStop(0, 'rgba(255,255,255,0)');
1893	  glowGrad.addColorStop(0.5, 'rgba(255,255,255,0.15)');
1894	  glowGrad.addColorStop(1, 'rgba(255,255,255,0)');
1895	  ctx.fillStyle = glowGrad;
1896	  ctx.fillRect(0, horizonY - 20, W, 60);
1897	
1898	  // ── Ground strip below horizon ───────────────────────────────────────
1899	  var groundGrad = ctx.createLinearGradient(0, horizonY + 20, 0, H);
1900	  groundGrad.addColorStop(0,    '#6b8c5c');  // distant green-brown
1901	  groundGrad.addColorStop(0.15, '#5a7a4a');
1902	  groundGrad.addColorStop(0.5,  R.CONFIG.TRACK_BG_COLOR || '#3a5a2c');
1903	  groundGrad.addColorStop(1,    '#2a4a1c');
