1907	  // ── Horizon line ─────────────────────────────────────────────────────
1908	  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
1909	  ctx.lineWidth   = 1;
1910	  ctx.beginPath();
1911	  ctx.moveTo(0, horizonY + 20);
1912	  ctx.lineTo(W, horizonY + 20);
