1918	/* ==========================================================================
1919	   R.renderTrack(ctx) — Main track rendering
1920	   ========================================================================== */
1921	
1922	/**
1923	 * Renders the racing track with pseudo-3D perspective.
1924	 *
1925	 * Drawing order: back-to-front (far segments first) for correct occlusion.
1926	 * For each consecutive segment pair, draws:
1927	 *   1. Road surface trapezoid
1928	 *   2. Edge lines (solid white)
1929	 *   3. Centre dashed lane markings
1930	 *   4. Red/white curbs on tight curves
1931	 *
1932	 * Operates in screen space: saves the camera transform, resets to identity,
1933	 * does perspective projection via worldToScreen, then restores.
1934	 *
1935	 * @param {CanvasRenderingContext2D} ctx
1936	 */
1937	R.renderTrack = function (ctx) {
1938	  var segs   = R.track.segments;
1939	  var n      = segs.length;
1940	  var total  = R.track.totalLength;
1941	  var cam    = R.camera;
1942	  var cfg    = R.CONFIG;
1943	  var W      = cfg.CANVAS_WIDTH;
1944	  var H      = cfg.CANVAS_HEIGHT;
1945	
1946	  if (!n) return;
1947	
1948	  // ── Update camera track position from player ────────────────────────
1949	  if (R.player) {
1950	    cam.worldZ = R.player.z;
1951	    // Compute camera's approximate track distance for forward-distance calc
1952	    var playerSegIdx = 0;
1953	    var bestD2 = Infinity;
1954	    for (var pidx = 0; pidx < n; pidx++) {
1955	      var pseg = segs[pidx];
1956	      var pdx  = pseg.worldX - R.player.x;
1957	      var pdz  = pseg.worldZ - R.player.z;
1958	      var pd2  = pdx * pdx + pdz * pdz;
1959	      if (pd2 < bestD2) { bestD2 = pd2; playerSegIdx = pidx; }
1960	    }
1961	    cam.trackDist = segs[playerSegIdx].dist;
1962	  } else {
1963	    cam.worldZ    = cam.worldZ || 0;
1964	    cam.trackDist = cam.trackDist || 0;
1965	  }
1966	
1967	  // ── Save canvas state, reset to identity for screen-space drawing ───
1968	  ctx.save();
1969	  ctx.setTransform(1, 0, 0, 1, 0, 0);
1970	
1971	  var renderDist = cfg.RENDER_DISTANCE;
1972	  var horY       = cfg.HORIZON_Y;
1973	  var camDist    = cam.trackDist;
1974	
1975	  // ── Collect visible segments with computed screen positions ──────────
1976	  var visible = [];
1977	  for (var i = 0; i < n; i++) {
1978	    var seg = segs[i];
1979	    var dz  = _forwardDist(seg.dist, camDist, total);
1980	
1981	    // Cull segments too far behind or ahead
1982	    if (dz < -renderDist || dz > renderDist * 1.4) continue;
1983	
1984	    // Compute screen position via perspective projection
1985	    var proj = _projectSegment(seg, dz, cam, cfg, W, H);
1986	
1987	    // Cull segments off-screen
1988	    if (proj.y > H + 100 || proj.y < -100) continue;
1989	
1990	    visible.push({
1991	      index: i,
1992	      seg:   seg,
1993	      dz:    dz,
1994	      sx:    proj.x,
1995	      sy:    proj.y,
1996	      scale: proj.scale,
1997	      lx:    proj.lx,
1998	      rx:    proj.rx
1999	    });
2000	  }
2001	
2002	  if (visible.length === 0) { ctx.restore(); return; }
2003	
2004	  // Sort far-to-near (back-to-front) for painter's algorithm
2005	  visible.sort(function (a, b) { return b.dz - a.dz; });
2006	
2007	  // ── Draw terrain / grass beneath the road ─────────────────────────────
2008	  // (A solid fill from horizon down, over which the road trapezoids sit)
2009	  ctx.fillStyle = cfg.TRACK_BG_COLOR || '#3a5a2c';
2010	  ctx.fillRect(0, horY + 20, W, H - horY - 20);
2011	
2012	  // ── Build a set of visible indices for fast pair-check ────────────────
2013	  var visSet = {};
2014	  for (var vi = 0; vi < visible.length; vi++) {
2015	    visSet[visible[vi].index] = vi;
2016	  }
2017	
2018	  // ── Track drawn-pair set to avoid double-drawing ─────────────────────
2019	  var drawnPairs = {};
2020	
2021	  // ── Pass 1: Road surface trapezoids ──────────────────────────────────
2022	  for (var vi2 = 0; vi2 < visible.length; vi2++) {
2023	    var cur  = visible[vi2];
2024	    var idx  = cur.index;
2025	    var nextIdx = (idx + 1) % n;
2026	
2027	    // Only draw if the next segment is also visible
2028	    if (!(nextIdx in visSet)) continue;
2029	
2030	    // Avoid double-draw: each pair is drawn when processing the farther segment
2031	    var pairKey = idx + '_' + nextIdx;
2032	    if (drawnPairs[pairKey]) continue;
2033	    drawnPairs[pairKey] = true;
2034	
2035	    var nxtVis = visible[visSet[nextIdx]];
2036	    // Use the stored screen coordinates
2037	    var clx = cur.lx, crx = cur.rx, csy = cur.sy;
2038	    var nlx = nxtVis.lx, nrx = nxtVis.rx, nsy = nxtVis.sy;
2039	
2040	    // ── Road surface colour (slight variation per segment) ─────────────
2041	    var baseColor = cfg.ROAD_COLOR || '#555';
2042	    var colorVar  = ((idx * 17) & 7) - 3; // pseudo-random ±3 per segment
2043	    var rgb = _adjustBrightness(baseColor, colorVar);
2044	    ctx.fillStyle = rgb;
2045	
2046	    // Draw the trapezoid: (clx,csy) → (crx,csy) → (nrx,nsy) → (nlx,nsy)
2047	    ctx.beginPath();
2048	    ctx.moveTo(clx, csy);
2049	    ctx.lineTo(crx, csy);
2050	    ctx.lineTo(nrx, nsy);
2051	    ctx.lineTo(nlx, nsy);
2052	    ctx.closePath();
2053	    ctx.fill();
2054	
2055	    // ── Edge lines ─────────────────────────────────────────────────────
2056	    ctx.strokeStyle = cfg.LINE_COLOR || '#fff';
2057	    ctx.lineWidth   = Math.max(cur.scale * 2.5, 1);
2058	    ctx.beginPath();
2059	    ctx.moveTo(clx, csy);
2060	    ctx.lineTo(nlx, nsy);
2061	    ctx.stroke();
2062	
2063	    ctx.beginPath();
2064	    ctx.moveTo(crx, csy);
2065	    ctx.lineTo(nrx, nsy);
2066	    ctx.stroke();
2067	
2068	    // ── Curbs on tight curves ──────────────────────────────────────────
2069	    if (Math.abs(cur.seg.curvature) > (cfg.CURB_CURVATURE_THRESH || 0.0012)) {
2070	      var curbW  = cfg.RUMBLE_WIDTH || 6;
2071	      var curbScale = Math.max(cur.scale * curbW, 1);
2072	      var isOuterRight = cur.seg.curvature < 0; // negative curvature = right turn, outer = left
2073	
2074	      if (isOuterRight) {
2075	        // Outer curb is on the left edge (outside of a right turn)
2076	        _drawCurbSegment(ctx, clx, csy, nlx, nsy, curbScale, cur.dz, cfg);
2077	      } else {
2078	        // Outer curb is on the right edge (outside of a left turn)
2079	        _drawCurbSegment(ctx, crx, csy, nrx, nsy, curbScale, cur.dz, cfg);
2080	      }
2081	    }
2082	  }
2083	
2084	  // ── Pass 2: Centre lane markings ─────────────────────────────────────
2085	  _drawLaneMarkings(ctx, visible, cfg, total);
2086	
2087	  ctx.restore();
2088	};
