2090	/* ==========================================================================
2091	   RENDERING HELPERS
2092	   ========================================================================== */
2093	
2094	/**
2095	 * Projects a single track segment to screen coordinates.
2096	 * Returns the centre screen position plus left/right edge positions.
2097	 *
2098	 * @param {Object} seg Segment object
2099	 * @param {number} dz  Forward distance from camera (signed)
2100	 * @param {Object} cam Camera object
2101	 * @param {Object} cfg CONFIG object
2102	 * @param {number} W   Canvas width
2103	 * @param {number} H   Canvas height
2104	 * @returns {{x:number, y:number, scale:number, lx:number, rx:number}}
2105	 */
2106	function _projectSegment(seg, dz, cam, cfg, W, H) {
2107	  var coeff    = cfg.PERSPECTIVE_COEFF;
2108	  var absDz    = dz < 0 ? -dz : dz;
2109	  var scale    = cam.zoom / (1 + absDz * coeff);
2110	
2111	  // Screen centre X — horizontal displacement from camera
2112	  var dx   = seg.worldX - cam.x;
2113	  var sx   = W / 2 + dx * scale;
2114	
2115	  // Screen centre Y — incorporates elevation and forward distance
2116	  // dz > 0 (ahead) → smaller sy (higher on screen, toward horizon)
2117	  // dz < 0 (behind) → larger sy (lower on screen)
2118	  var dy   = seg.worldY - cam.y;
2119	  var sy   = H / 2 + dy * scale - dz * cfg.ROAD_V_OFFSET * scale;
2120	
2121	  // Left/right edge screen positions
2122	  var halfW = seg.width / 2;
2123	  // Left edge: offset perpendicular to segment direction
2124	  var cosA = Math.cos(seg.angle);
2125	  var sinA = Math.sin(seg.angle);
2126	  // Left = direction * halfWidth rotated 90° counter-clockwise
2127	  var leftDx  = dx + cosA * halfW;
2128	  var rightDx = dx - cosA * halfW;
2129	  // Screen X for edges (same Y as centre, same scale)
2130	  var lx = W / 2 + leftDx  * scale;
2131	  var rx = W / 2 + rightDx * scale;
2132	
2133	  return { x: sx, y: sy, scale: scale, lx: lx, rx: rx };
2134	}
2135	
2136	/**
2137	 * Draws a single curb stripe segment between two screen-space points.
2138	 * Alternates red/white based on distance along the track.
2139	 *
2140	 * @param {CanvasRenderingContext2D} ctx
2141	 * @param {number} x1  Start X on screen
2142	 * @param {number} y1  Start Y on screen
2143	 * @param {number} x2  End X on screen
2144	 * @param {number} y2  End Y on screen
2145	 * @param {number} w   Curb width in screen pixels
2146	 * @param {number} dz  Forward distance (for stripe index)
2147	 * @param {Object} cfg CONFIG
2148	 */
2149	function _drawCurbSegment(ctx, x1, y1, x2, y2, w, dz, cfg) {
2150	  var stripeLen = 25; // world units per stripe
2151	  var idx = Math.floor(Math.abs(dz) / stripeLen);
2152	  var color = (idx % 2 === 0) ? (cfg.RUMBLE_COLOR_A || '#ff0000')
2153	                              : (cfg.RUMBLE_COLOR_B || '#ffffff');
2154	  ctx.strokeStyle = color;
2155	  ctx.lineWidth   = Math.max(w, 1.5);
2156	  ctx.beginPath();
2157	  ctx.moveTo(x1, y1);
2158	  ctx.lineTo(x2, y2);
2159	  ctx.stroke();
2160	}
2161	
2162	/**
2163	 * Draws dashed centre-line markings across visible road segments.
2164	 *
2165	 * @param {CanvasRenderingContext2D} ctx
2166	 * @param {Array}  visible Array of visible segment entries (sorted far→near)
2167	 * @param {Object} cfg     CONFIG
2168	 * @param {number} total   Total track length
2169	 */
2170	function _drawLaneMarkings(ctx, visible, cfg, total) {
2171	  var dashLen  = cfg.LANE_MARKER_DASH || 40;
2172	  var gapLen   = cfg.LANE_MARKER_GAP  || 30;
2173	  var cycleLen = dashLen + gapLen;
2174	
2175	  ctx.strokeStyle = cfg.LANE_MARKER_COLOR || '#ccc';
2176	
2177	  for (var vi = 0; vi < visible.length; vi++) {
2178	    var cur = visible[vi];
2179	    var seg = cur.seg;
2180	    var d   = seg.dist;
2181	
2182	    // Determine if this segment is in a dash or gap
2183	    var cyclePos = d % cycleLen;
2184	    if (cyclePos < 0) cyclePos += cycleLen;
2185	    if (cyclePos >= dashLen) continue; // gap — skip
2186	
2187	    var lineW = Math.max(cur.scale * (cfg.LANE_MARKER_WIDTH || 1.5), 0.6);
2188	    ctx.lineWidth = lineW;
2189	
2190	    // Draw from centre position of this segment toward next
2191	    // Use a short dash at the segment centre
2192	    var dashScreenLen = Math.max(cur.scale * dashLen * 0.3, 3);
2193	    var angle = seg.angle;
2194	    var cosA  = Math.cos(angle);
2195	    var sinA  = Math.sin(angle);
2196	    // Forward direction in screen space (from the centre point)
2197	    var fx = sinA * cur.scale * 8; // forward component projected to screen X
2198	    var fy = -cfg.ROAD_V_OFFSET * cur.scale * 8; // forward component in screen Y
2199	
2200	    ctx.beginPath();
2201	    ctx.moveTo(cur.sx - fx, cur.sy - fy);
2202	    ctx.lineTo(cur.sx + fx, cur.sy + fy);
2203	    ctx.stroke();
2204	  }
2205	}
2206	
2207	/**
2208	 * Adjusts a hex colour string's brightness by a signed integer amount.
2209	 * Preserves the colour format (#xxx or #xxxxxx).
2210	 *
2211	 * @param {string} hex    Hex colour (e.g. '#555')
2212	 * @param {number} amount Signed adjustment (-255 to 255)
2213	 * @returns {string} Adjusted hex colour
2214	 */
2215	function _adjustBrightness(hex, amount) {
2216	  if (hex.charAt(0) === '#') hex = hex.slice(1);
2217	  if (hex.length === 3) {
2218	    hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
2219	  }
2220	  var r = Math.min(255, Math.max(0, parseInt(hex.slice(0, 2), 16) + amount));
2221	  var g = Math.min(255, Math.max(0, parseInt(hex.slice(2, 4), 16) + amount));
2222	  var b = Math.min(255, Math.max(0, parseInt(hex.slice(4, 6), 16) + amount));
2223	  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
2224	}
