2227	   R.getTrackDistanceAt(wx, wz) — Utility for AI / position tracking
2228	   ========================================================================== */
2229	
2230	/**
2231	 * Returns the cumulative track distance of the nearest point on the track
2232	 * centre-line to the given world position. Useful for AI lap tracking.
2233	 *
2234	 * @param {number} wx World X coordinate
2235	 * @param {number} wz World Z coordinate
2236	 * @returns {number} Track distance at nearest centre-line point
2237	 */
2238	R.getTrackDistanceAt = function (wx, wz) {
2239	  var segs  = R.track.segments;
2240	  var n     = segs.length;
2241	  var bestIdx   = 0;
2242	  var bestDist2 = Infinity;
2243	  for (var i = 0; i < n; i++) {
2244	    var dx = segs[i].worldX - wx;
2245	    var dz = segs[i].worldZ - wz;
2246	    var d2 = dx * dx + dz * dz;
2247	    if (d2 < bestDist2) {
2248	      bestDist2 = d2;
2249	      bestIdx   = i;
2250	    }
2251	  }
2252	  return segs[bestIdx].dist;
2253	};
