2255	/* ==========================================================================
2256	   R.getSegmentAtDistance(dist) — Direct segment access
2257	   ========================================================================== */
2258	
2259	/**
2260	 * Returns the segment object at a given track distance (no interpolation).
2261	 * Wraps around for closed circuit.
2262	 *
2263	 * @param {number} dist Cumulative track distance
2264	 * @returns {Object} The segment at that distance
2265	 */
2266	R.getSegmentAtDistance = function (dist) {
2267	  var segs  = R.track.segments;
2268	  var total = R.track.totalLength;
2269	  var n     = segs.length;
2270	  var d     = dist % total;
2271	  if (d < 0) d += total;
2272	
2273	  var lo = 0, hi = n - 1;
2274	  while (lo < hi) {
2275	    var mid = (lo + hi + 1) >> 1;
2276	    if (segs[mid].dist <= d) lo = mid;
2277	    else hi = mid - 1;
2278	  }
2279	  return segs[lo];
2280	};
