2282	/* ==========================================================================
2283	   R.getTrackWidth(dist) — Quick width lookup (AI avoidance)
2284	   ========================================================================== */
2285	
2286	/**
2287	 * Returns the interpolated road width at a given track distance.
2288	 * Convenience wrapper for AI / collision systems.
2289	 *
2290	 * @param {number} dist Cumulative track distance
2291	 * @returns {number} Road width in world units
2292	 */
2293	R.getTrackWidth = function (dist) {
2294	  var pos = R.getTrackPosition(dist);
2295	  return pos.width;
2296	};
