2299	   R.isOnTrackExtended(wx, wy, wz) — Full 3D collision check
2300	   ========================================================================== */
2301	
2302	/**
2303	 * Extended on-track check that also verifies elevation proximity.
2304	 * Useful for respawn logic or when cars go airborne (future).
2305	 * Falls back to 2D check if worldY is unavailable.
2306	 *
2307	 * @param {number} wx World X
2308	 * @param {number} wy World Y (elevation)
2309	 * @param {number} wz World Z
2310	 * @returns {{onTrack:boolean, distFromCenter:number, segmentIndex:number, elevationOk:boolean}}
2311	 */
2312	R.isOnTrackExtended = function (wx, wy, wz) {
2313	  var result = R.isOnTrack(wx, wz);
2314	
2315	  if (!result.onTrack) return result;
2316	
2317	  // Check elevation proximity
2318	  var seg       = R.track.segments[result.segmentIndex];
2319	  var elevDiff  = Math.abs(wy - seg.worldY);
2320	  var elevOk    = elevDiff < 80; // within 80 world units of segment elevation
2321	
2322	  return {
2323	    onTrack:        result.onTrack && elevOk,
2324	    distFromCenter: result.distFromCenter,
2325	    segmentIndex:   result.segmentIndex,
2326	    halfWidth:      result.halfWidth,
2327	    elevationOk:    elevOk
2328	  };
2329	};
