8295	/**
8296	 * Weighted random selection from SCENERY_TYPES using SCENERY_WEIGHTS.
8297	 * @returns {string} scenery type key
8298	 */
8299	function weightedRandomType() {
8300	  let total = 0;
8301	  for (let i = 0; i < SCENERY_WEIGHTS.length; i++) {
8302	    total += SCENERY_WEIGHTS[i];
8303	  }
8304	  let roll = Math.random() * total;
8305	  for (let i = 0; i < SCENERY_WEIGHTS.length; i++) {
8306	    roll -= SCENERY_WEIGHTS[i];
8307	    if (roll <= 0) {
8308	      return SCENERY_TYPES[i];
8309	    }
8310	  }
8311	  return 'tree';
8312	}
