8314	/**
8315	 * Random int in [min, max].
8316	 */
8317	function randInt(min, max) {
8318	  return Math.floor(Math.random() * (max - min + 1)) + min;
8319	}
8320	
8321	/**
8322	 * Random float in [min, max].
8323	 */
8324	function randFloat(min, max) {
8325	  return Math.random() * (max - min) + min;
8326	}
8327	
8328	/**
8329	 * Pick a random element from an array.
8330	 */
8331	function randPick(arr) {
8332	  return arr[Math.floor(Math.random() * arr.length)];
8333	}
