8349	/**
8350	 * Compute screen-space depth from world position relative to camera.
8351	 * Positive z means farther away (on screen, y goes down; worldZ tilts toward horizon).
8352	 */
8353	function computeScreenDepth(worldX, worldY, worldZ, camX, camY) {
8354	  // Approximate: distance from camera position (ignoring z for simplicity)
8355	  var dx = worldX - camX;
8356	  var dy = worldY - camY;
8357	  var dist = Math.sqrt(dx * dx + dy * dy);
8358	  return dist + worldZ * 0.5; // z pushes into depth
8359	}
