8361	// ---------------------------------------------------------------------------
8362	// R.initScenery — populate R.sceneryObjects along the track
8363	// ---------------------------------------------------------------------------
8364	R.initScenery = function () {
8365	  R.sceneryObjects = [];
8366	  var segments = R.track.segments;
8367	  if (!segments || segments.length === 0) return;
8368	
8369	  var step = R.CONFIG.SCENERY_SEGMENT_STEP;
8370	  var totalSegments = segments.length;
8371	  var startFinishSeg = R.CONFIG.SCENERY_GRANDSTAND_SEGMENT_INDEX;
8372	
8373	  // Pre-compute per-segment direction vectors for perpendicular offsets
8374	  var dirs = [];
8375	  for (var i = 0; i < totalSegments; i++) {
8376	    var prev = segments[(i - 1 + totalSegments) % totalSegments];
8377	    var curr = segments[i];
8378	    var dx = curr.worldX - prev.worldX;
8379	    var dy = curr.worldY - prev.worldY;
8380	    var len = Math.sqrt(dx * dx + dy * dy);
8381	    if (len < 1) {
8382	      // degenerate — reuse previous dir
8383	      dirs.push(dirs.length > 0 ? dirs[dirs.length - 1] : { dx: 1, dy: 0, len: 1 });
8384	    } else {
8385	      dirs.push({ dx: dx / len, dy: dy / len, len: len });
8386	    }
8387	  }
8388	
8389	  // Place grandstand near start/finish line, off to the right
8390	  var startSeg = segments[startFinishSeg];
8391	  var startDir = dirs[startFinishSeg];
8392	  var perpX = -startDir.dy; // right perpendicular
8393	  var perpY = startDir.dx;
8394	  R.sceneryObjects.push({
8395	    worldX: startSeg.worldX + perpX * 150,
8396	    worldY: startSeg.worldY + perpY * 150,
8397	    worldZ: startSeg.worldZ,
8398	    type: 'grandstand',
8399	    width: 300,
8400	    height: 120,
8401	    color: randPick(BUILDING_COLORS),
8402	    variant: 1
8403	  });
8404	
8405	  // Generate scenery along every Nth segment
8406	  var buildingClusterSegments = [];
8407	  for (var s = 0; s < totalSegments; s += step) {
8408	    var seg = segments[s];
8409	    var dir = dirs[s];
8410	    var perpRightX = -dir.dy;
8411	    var perpRightY = dir.dx;
8412	
8413	    // Determine if this segment is near start/finish (for building clustering)
8414	    var distFromHome = Math.min(
8415	      Math.abs(s - startFinishSeg),
8416	      totalSegments - Math.abs(s - startFinishSeg)
8417	    );
8418	
8419	    // Choose type — rural vs urban bias
8420	    var rawType = weightedRandomType();
8421	    if (rawType === 'building') {
8422	      if (distFromHome > R.CONFIG.SCENERY_BUILDING_CLUSTER_RANGE) {
8423	        // Far from start/finish — convert some buildings to trees
8424	        if (Math.random() < 0.7) rawType = 'tree';
8425	      }
8426	    }
8427	    if (rawType === 'tree') {
8428	      if (distFromHome <= R.CONFIG.SCENERY_BUILDING_CLUSTER_RANGE && Math.random() < 0.3) {
8429	        rawType = 'building'; // some trees become buildings near start/finish
8430	      }
8431	    }
8432	
8433	    // Only one grandstand (placed above)
8434	    if (rawType === 'grandstand') {
8435	      rawType = 'building';
8436	    }
8437	
8438	    // Choose side: left or right (biased toward outside of curves)
8439	    var side = Math.random() < 0.5 ? 1 : -1;
8440	    if (seg.curvature !== undefined && seg.curvature !== 0) {
8441	      // Bias toward outside of curve
8442	      side = seg.curvature > 0 ? 1 : -1;
8443	      if (Math.random() < 0.3) side = -side; // 30% chance of inner placement
8444	    }
8445	
8446	    var offsetDist = randFloat(
8447	      R.CONFIG.SCENERY_TRACK_EDGE_OFFSET_MIN,
8448	      R.CONFIG.SCENERY_TRACK_EDGE_OFFSET_MAX
8449	    ) + seg.width * 0.5;
8450	
8451	    var obj = {
8452	      worldX: seg.worldX + perpRightX * offsetDist * side,
8453	      worldY: seg.worldY + perpRightY * offsetDist * side,
8454	      worldZ: seg.worldZ || 0,
8455	      type: rawType,
8456	      width: 0,
8457	      height: 0,
8458	      color: '',
8459	      variant: 0,
8460	      rotation: 0
8461	    };
8462	
8463	    // Tune dimensions and color by type
8464	    switch (rawType) {
8465	      case 'building':
8466	        obj.width = randInt(30, 90);
8467	        obj.height = randInt(40, 160);
8468	        obj.color = randPick(BUILDING_COLORS);
8469	        obj.variant = randInt(0, 3); // 0=flat roof, 1=peaked, 2=wide, 3=tall+narrow
8470	        buildingClusterSegments.push(s);
8471	        break;
8472	
8473	      case 'tree':
8474	        obj.width = randInt(18, 40);
8475	        obj.height = randInt(30, 70);
8476	        obj.color = randPick(TREE_GREENS);
8477	        obj.variant = randInt(0, 2); // 0=round, 1=pine, 2=double-canopy
8478	        obj.rotation = randFloat(-0.3, 0.3); // slight random lean
8479	        break;
8480	
8481	      case 'billboard':
8482	        obj.width = randInt(40, 70);
8483	        obj.height = randInt(50, 90);
8484	        obj.color = randPick(BILLBOARD_COLORS);
8485	        obj.variant = randInt(0, 1); // 0=single pole, 1=double pole
8486	        break;
8487	
8488	      case 'barrier':
8489	        obj.width = randInt(15, 30);
8490	        obj.height = randInt(8, 16);
8491	        obj.color = '#cc0000'; // red base, white stripes added in render
8492	        obj.variant = 0;
8493	        // Place barriers closer to track edge
8494	        obj.worldX = seg.worldX + perpRightX * (seg.width * 0.5 + randInt(5, 15)) * side;
8495	        obj.worldY = seg.worldY + perpRightY * (seg.width * 0.5 + randInt(5, 15)) * side;
8496	        break;
8497	
8498	      default:
8499	        break;
8500	    }
8501	
8502	    R.sceneryObjects.push(obj);
8503	  }
8504	
8505	  // Depth-sort by worldZ + distance from origin (approximate back-to-front for rendering)
8506	  // We'll sort per-frame in render for accurate camera-relative depth.
8507	};
