8509	// ---------------------------------------------------------------------------
8510	// R.renderScenery — render visible scenery objects
8511	// ---------------------------------------------------------------------------
8512	R.renderScenery = function () {
8513	  var ctx = R.ctx;
8514	  var cam = R.camera;
8515	  var cullDist = R.CONFIG.SCENERY_CULL_DISTANCE;
8516	  var margin = R.CONFIG.SCENERY_CULL_MARGIN;
8517	  var objects = R.sceneryObjects;
8518	  var n = objects.length;
8519	  if (n === 0) return;
8520	
8521	  var camX = cam.x;
8522	  var camY = cam.y;
8523	
8524	  // First pass: compute screen positions and depth, collect visible objects
8525	  var visible = [];
8526	  for (var i = 0; i < n; i++) {
8527	    var obj = objects[i];
8528	    var screen = R.worldToScreen
8529	      ? R.worldToScreen(obj.worldX, obj.worldY, obj.worldZ)
8530	      : defaultWorldToScreen(obj.worldX, obj.worldY, obj.worldZ, camX, camY, cam.zoom);
8531	
8532	    if (!screen || !screen.visible) continue;
8533	
8534	    // Cull by screen-space bounding box with margin
8535	    var hw = obj.width * screen.scale * 0.5;
8536	    var hh = obj.height * screen.scale * 0.5;
8537	    if (screen.x + hw < -margin || screen.x - hw > R.canvas.width + margin ||
8538	        screen.y + hh < -margin || screen.y - hh > R.canvas.height + margin) {
8539	      continue;
8540	    }
8541	
8542	    // Depth for sorting
8543	    obj._depth = computeScreenDepth(obj.worldX, obj.worldY, obj.worldZ, camX, camY);
8544	    obj._screenX = screen.x;
8545	    obj._screenY = screen.y;
8546	    obj._scale = screen.scale;
8547	    visible.push(obj);
8548	  }
8549	
8550	  // Sort by depth (far to near — paint back to front)
8551	  visible.sort(function (a, b) { return b._depth - a._depth; });
8552	
8553	  // Second pass: draw each visible object
8554	  for (var v = 0; v < visible.length; v++) {
8555	    var o = visible[v];
8556	    ctx.save();
8557	    drawSceneryObject(ctx, o, o._screenX, o._screenY, o._scale);
8558	    ctx.restore();
8559	  }
8560	};
