8562	// ---------------------------------------------------------------------------
8563	// drawSceneryObject — route to type-specific renderer
8564	// ---------------------------------------------------------------------------
8565	function drawSceneryObject(ctx, obj, sx, sy, scale) {
8566	  switch (obj.type) {
8567	    case 'building':
8568	      drawBuilding(ctx, obj, sx, sy, scale);
8569	      break;
8570	    case 'tree':
8571	      drawTree(ctx, obj, sx, sy, scale);
8572	      break;
8573	    case 'billboard':
8574	      drawBillboard(ctx, obj, sx, sy, scale);
8575	      break;
8576	    case 'barrier':
8577	      drawBarrier(ctx, obj, sx, sy, scale);
8578	      break;
8579	    case 'grandstand':
8580	      drawGrandstand(ctx, obj, sx, sy, scale);
8581	      break;
8582	    default:
8583	      break;
8584	  }
8585	}
