8587	// ---------------------------------------------------------------------------
8588	// drawBuilding — rectangle body + windows + roof + shadow
8589	// ---------------------------------------------------------------------------
8590	function drawBuilding(ctx, obj, sx, sy, scale) {
8591	  var w = obj.width * scale;
8592	  var h = obj.height * scale;
8593	  var x = sx - w * 0.5;
8594	  var y = sy - h; // bottom-aligned at ground
8595	
8596	  // Shadow
8597	  ctx.fillStyle = 'rgba(0,0,0,0.25)';
8598	  ctx.beginPath();
8599	  ctx.ellipse(sx, sy, w * 0.55, w * 0.15, 0, 0, Math.PI * 2);
8600	  ctx.fill();
8601	
8602	  // Building body
8603	  ctx.fillStyle = obj.color;
8604	  ctx.fillRect(x, y, w, h);
8605	
8606	  // Outline
8607	  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8608	  ctx.lineWidth = Math.max(1, scale * 1.5);
8609	  ctx.strokeRect(x, y, w, h);
8610	
8611	  // Windows
8612	  var windowCols = Math.max(2, Math.floor(w / (10 * scale)));
8613	  var windowRows = Math.max(2, Math.floor(h / (14 * scale)));
8614	  if (windowCols < 1) windowCols = 1;
8615	  if (windowRows < 1) windowRows = 1;
8616	  var winW = (w * 0.7) / windowCols;
8617	  var winH = (h * 0.6) / windowRows;
8618	  var startX = x + w * 0.15;
8619	  var startY = y + h * 0.1;
8620	
8621	  // Seed deterministic per-building window pattern
8622	  var seed = (obj.worldX * 31 + obj.worldY * 17) % 1000;
8623	
8624	  for (var row = 0; row < windowRows; row++) {
8625	    for (var col = 0; col < windowCols; col++) {
8626	      var lit = ((seed + row * 7 + col * 13) % 5) < 3; // ~60% lit
8627	      ctx.fillStyle = lit
8628	        ? 'rgba(255,255,200,0.75)'
8629	        : 'rgba(40,40,60,0.6)';
8630	      var wx = startX + col * (winW + w * 0.02);
8631	      var wy = startY + row * (winH + h * 0.03);
8632	      ctx.fillRect(wx, wy, winW, winH);
8633	
8634	      // Window frame
8635	      ctx.strokeStyle = lit ? 'rgba(0,0,0,0.2)' : 'rgba(0,0,0,0.35)';
8636	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
8637	      ctx.strokeRect(wx, wy, winW, winH);
8638	    }
8639	  }
8640	
8641	  // Door
8642	  var doorW = w * 0.18;
8643	  var doorH = h * 0.25;
8644	  var doorX = sx - doorW * 0.5;
8645	  var doorY = sy - doorH;
8646	  ctx.fillStyle = 'rgba(60,40,30,0.8)';
8647	  ctx.fillRect(doorX, doorY, doorW, doorH);
8648	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
8649	  ctx.lineWidth = Math.max(0.5, scale * 0.7);
8650	  ctx.strokeRect(doorX, doorY, doorW, doorH);
8651	  // Doorknob
8652	  ctx.fillStyle = 'rgba(200,180,100,0.7)';
8653	  ctx.beginPath();
8654	  ctx.arc(doorX + doorW * 0.8, doorY + doorH * 0.5, Math.max(1, scale * 1.5), 0, Math.PI * 2);
8655	  ctx.fill();
8656	
8657	  // Roof
8658	  var roofH = h * 0.15;
8659	  switch (obj.variant) {
8660	    case 0: // flat roof — slightly wider
8661	      ctx.fillStyle = randPick(ROOF_COLORS);
8662	      ctx.fillRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
8663	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8664	      ctx.lineWidth = Math.max(0.5, scale * 0.7);
8665	      ctx.strokeRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
8666	      break;
8667	
8668	    case 1: // peaked roof (triangle)
8669	      ctx.fillStyle = randPick(ROOF_COLORS);
8670	      ctx.beginPath();
8671	      ctx.moveTo(x - w * 0.08, y);
8672	      ctx.lineTo(sx, y - roofH * 2);
8673	      ctx.lineTo(x + w + w * 0.08, y);
8674	      ctx.closePath();
8675	      ctx.fill();
8676	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8677	      ctx.lineWidth = Math.max(0.5, scale * 0.7);
8678	      ctx.stroke();
8679	      break;
8680	
8681	    case 2: // wide building — flat with slight overhang
8682	      ctx.fillStyle = randPick(ROOF_COLORS);
8683	      ctx.fillRect(x - w * 0.08, y - roofH, w * 1.16, roofH);
8684	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
8685	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
8686	      ctx.strokeRect(x - w * 0.08, y - roofH, w * 1.16, roofH);
8687	      break;
8688	
8689	    case 3: // tall narrow — flat roof + chimney
8690	      ctx.fillStyle = randPick(ROOF_COLORS);
8691	      ctx.fillRect(x - w * 0.04, y - roofH, w * 1.08, roofH);
8692	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
8693	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
8694	      ctx.strokeRect(x - w * 0.04, y - roofH, w * 1.08, roofH);
8695	      // Chimney
8696	      var chimW = w * 0.12;
8697	      var chimH = roofH * 3;
8698	      ctx.fillStyle = '#8b4513';
8699	      ctx.fillRect(x + w * 0.65, y - roofH - chimH, chimW, chimH);
8700	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8701	      ctx.lineWidth = Math.max(0.3, scale * 0.4);
8702	      ctx.strokeRect(x + w * 0.65, y - roofH - chimH, chimW, chimH);
8703	      break;
8704	
8705	    default:
8706	      ctx.fillStyle = randPick(ROOF_COLORS);
8707	      ctx.fillRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
8708	      break;
8709	  }
8710	}
