8712	// ---------------------------------------------------------------------------
8713	// drawTree — circle canopy on brown trunk
8714	// ---------------------------------------------------------------------------
8715	function drawTree(ctx, obj, sx, sy, scale) {
8716	  var w = obj.width * scale;
8717	  var h = obj.height * scale;
8718	  var trunkW = w * 0.2;
8719	  var trunkH = h * 0.4;
8720	  var canopyR = w * 0.5;
8721	
8722	  // Rotation for slight lean
8723	  var rot = obj.rotation || 0;
8724	
8725	  ctx.save();
8726	  if (rot !== 0) {
8727	    ctx.translate(sx, sy);
8728	    ctx.rotate(rot);
8729	    ctx.translate(-sx, -sy);
8730	  }
8731	
8732	  // Shadow
8733	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
8734	  ctx.beginPath();
8735	  ctx.ellipse(sx, sy, canopyR * 0.8, canopyR * 0.2, 0, 0, Math.PI * 2);
8736	  ctx.fill();
8737	
8738	  // Trunk
8739	  var trunkX = sx - trunkW * 0.5;
8740	  var trunkY = sy - trunkH - canopyR * 0.3;
8741	  ctx.fillStyle = '#6b4226';
8742	  ctx.fillRect(trunkX, trunkY, trunkW, trunkH);
8743	  ctx.strokeStyle = 'rgba(0,0,0,0.2)';
8744	  ctx.lineWidth = Math.max(0.5, scale * 0.5);
8745	  ctx.strokeRect(trunkX, trunkY, trunkW, trunkH);
8746	
8747	  // Canopy
8748	  var canopyY = trunkY - canopyR * 0.5;
8749	  var green = obj.color;
8750	
8751	  switch (obj.variant) {
8752	    case 0: // round canopy
8753	      ctx.fillStyle = green;
8754	      ctx.beginPath();
8755	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
8756	      ctx.fill();
8757	      // Highlight
8758	      ctx.fillStyle = 'rgba(255,255,255,0.12)';
8759	      ctx.beginPath();
8760	      ctx.arc(sx - canopyR * 0.2, canopyY - canopyR * 0.2, canopyR * 0.5, 0, Math.PI * 2);
8761	      ctx.fill();
8762	      // Outline
8763	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
8764	      ctx.lineWidth = Math.max(0.5, scale * 0.6);
8765	      ctx.beginPath();
8766	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
8767	      ctx.stroke();
8768	      break;
8769	
8770	    case 1: // pine tree — triangular tiers
8771	      var pineCY = trunkY - canopyR * 0.0;
8772	      for (var tier = 0; tier < 3; tier++) {
8773	        var tierW = canopyR * (1.2 - tier * 0.35);
8774	        var tierH = canopyR * 0.8;
8775	        var tierTopY = pineCY - tier * tierH * 0.5;
8776	        ctx.fillStyle = tier === 0 ? green : shadeColor(green, -10 * tier);
8777	        ctx.beginPath();
8778	        ctx.moveTo(sx, tierTopY - tierH);
8779	        ctx.lineTo(sx - tierW, tierTopY);
8780	        ctx.lineTo(sx + tierW, tierTopY);
8781	        ctx.closePath();
8782	        ctx.fill();
8783	        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
8784	        ctx.lineWidth = Math.max(0.5, scale * 0.4);
8785	        ctx.stroke();
8786	      }
8787	      break;
8788	
8789	    case 2: // double canopy — two overlapping circles
8790	      var c1Y = canopyY - canopyR * 0.1;
8791	      ctx.fillStyle = green;
8792	      ctx.beginPath();
8793	      ctx.arc(sx - canopyR * 0.25, c1Y, canopyR * 0.7, 0, Math.PI * 2);
8794	      ctx.fill();
8795	      ctx.fillStyle = shadeColor(green, 10);
8796	      ctx.beginPath();
8797	      ctx.arc(sx + canopyR * 0.25, c1Y, canopyR * 0.65, 0, Math.PI * 2);
8798	      ctx.fill();
8799	      // Highlight
8800	      ctx.fillStyle = 'rgba(255,255,255,0.1)';
8801	      ctx.beginPath();
8802	      ctx.arc(sx - canopyR * 0.35, c1Y - canopyR * 0.2, canopyR * 0.3, 0, Math.PI * 2);
8803	      ctx.fill();
8804	      break;
8805	
8806	    default:
8807	      ctx.fillStyle = green;
8808	      ctx.beginPath();
8809	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
8810	      ctx.fill();
8811	      break;
8812	  }
8813	
8814	  ctx.restore();
8815	}
