8817	// ---------------------------------------------------------------------------
8818	// drawBillboard — tall rectangle with colored ad
8819	// ---------------------------------------------------------------------------
8820	function drawBillboard(ctx, obj, sx, sy, scale) {
8821	  var w = obj.width * scale;
8822	  var h = obj.height * scale;
8823	  var poleW = Math.max(2, w * 0.12);
8824	  var poleH = h * 0.25;
8825	  var boardH = h * 0.75;
8826	  var x = sx - w * 0.5;
8827	  var y = sy - h;
8828	
8829	  // Shadow
8830	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
8831	  ctx.beginPath();
8832	  ctx.ellipse(sx, sy, w * 0.45, w * 0.1, 0, 0, Math.PI * 2);
8833	  ctx.fill();
8834	
8835	  // Pole(s)
8836	  ctx.fillStyle = '#555555';
8837	  if (obj.variant === 0) {
8838	    // Single center pole
8839	    ctx.fillRect(sx - poleW * 0.5, sy - poleH, poleW, poleH);
8840	  } else {
8841	    // Double poles
8842	    ctx.fillRect(x + w * 0.15, sy - poleH, poleW, poleH);
8843	    ctx.fillRect(x + w * 0.85 - poleW, sy - poleH, poleW, poleH);
8844	  }
8845	
8846	  // Board background (white)
8847	  var boardX = x;
8848	  var boardY = y;
8849	  ctx.fillStyle = '#f8f8f8';
8850	  ctx.fillRect(boardX, boardY, w, boardH);
8851	
8852	  // Colored ad panel (center portion)
8853	  var adPadding = w * 0.08;
8854	  var adX = boardX + adPadding;
8855	  var adY = boardY + adPadding;
8856	  var adW = w - adPadding * 2;
8857	  var adH = boardH * 0.55;
8858	  ctx.fillStyle = obj.color;
8859	  ctx.fillRect(adX, adY, adW, adH);
8860	
8861	  // "Text" lines on ad
8862	  ctx.fillStyle = 'rgba(255,255,255,0.9)';
8863	  var lineH = Math.max(1, adH * 0.08);
8864	  var lines = 3;
8865	  for (var li = 0; li < lines; li++) {
8866	    var lw = adW * (0.5 + Math.random() * 0.4);
8867	    var lx = adX + adW * 0.1;
8868	    var ly = adY + adH * 0.25 + li * adH * 0.25;
8869	    ctx.fillRect(lx, ly, lw, lineH);
8870	  }
8871	
8872	  // Bottom text area
8873	  var bottomY = adY + adH + adPadding * 0.5;
8874	  ctx.fillStyle = 'rgba(0,0,0,0.15)';
8875	  ctx.fillRect(adX, bottomY, adW, Math.max(2, boardH * 0.12));
8876	
8877	  // Border
8878	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
8879	  ctx.lineWidth = Math.max(1, scale * 1);
8880	  ctx.strokeRect(boardX, boardY, w, boardH);
8881	}
