8886	function drawBarrier(ctx, obj, sx, sy, scale) {
8887	  var w = obj.width * scale;
8888	  var h = obj.height * scale;
8889	  var x = sx - w * 0.5;
8890	  var y = sy - h;
8891	
8892	  // Shadow
8893	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
8894	  ctx.beginPath();
8895	  ctx.ellipse(sx, sy, w * 0.45, w * 0.08, 0, 0, Math.PI * 2);
8896	  ctx.fill();
8897	
8898	  // Barrier body with stripes
8899	  var stripeCount = Math.max(2, Math.floor(w / (6 * scale)));
8900	  var stripeW = w / stripeCount;
8901	
8902	  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8903	  ctx.lineWidth = Math.max(0.5, scale * 0.5);
8904	
8905	  for (var s = 0; s < stripeCount; s++) {
8906	    ctx.fillStyle = s % 2 === 0 ? '#cc0000' : '#ffffff';
8907	    var sx2 = x + s * stripeW;
8908	    ctx.fillRect(sx2, y, stripeW, h);
8909	    ctx.strokeRect(sx2, y, stripeW, h);
8910	  }
8911	}
