8913	// ---------------------------------------------------------------------------
8914	// drawGrandstand — multi-tier seating structure
8915	// ---------------------------------------------------------------------------
8916	function drawGrandstand(ctx, obj, sx, sy, scale) {
8917	  var w = obj.width * scale;
8918	  var h = obj.height * scale;
8919	  var x = sx - w * 0.5;
8920	  var y = sy - h;
8921	  var tiers = 6;
8922	  var tierH = h * 0.55 / tiers; // seating takes bottom 55%
8923	  var roofH = h * 0.45;
8924	  var tierOffset = w * 0.03;
8925	
8926	  // Shadow
8927	  ctx.fillStyle = 'rgba(0,0,0,0.3)';
8928	  ctx.beginPath();
8929	  ctx.ellipse(sx, sy, w * 0.6, w * 0.12, 0, 0, Math.PI * 2);
8930	  ctx.fill();
8931	
8932	  // Main structure
8933	  ctx.fillStyle = '#888888';
8934	  ctx.fillRect(x, y, w, h);
8935	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
8936	  ctx.lineWidth = Math.max(1, scale * 1.5);
8937	  ctx.strokeRect(x, y, w, h);
8938	
8939	  // Seating tiers — each row a different color
8940	  var tierColors = ['#cc3333', '#3366cc', '#33aa33', '#ccaa33', '#aa3366', '#33aaaa'];
8941	  var baseY = y + roofH;
8942	  for (var t = 0; t < tiers; t++) {
8943	    var tw = w - t * tierOffset * 2; // each tier slightly narrower
8944	    var tx = x + t * tierOffset;
8945	    var ty = baseY + t * tierH;
8946	    ctx.fillStyle = tierColors[t % tierColors.length];
8947	    ctx.fillRect(tx, ty, tw, tierH);
8948	    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
8949	    ctx.lineWidth = Math.max(0.5, scale * 0.4);
8950	    ctx.strokeRect(tx, ty, tw, tierH);
8951	
8952	    // Row of seat dots
8953	    if (tw > 8 && tierH > 3) {
8954	      var dotCount = Math.floor(tw / (3 * scale));
8955	      var dotSpacing = tw / (dotCount + 1);
8956	      ctx.fillStyle = 'rgba(255,255,255,0.3)';
8957	      for (var d = 0; d < dotCount; d++) {
8958	        var dx = tx + (d + 1) * dotSpacing;
8959	        ctx.beginPath();
8960	        ctx.arc(dx, ty + tierH * 0.5, Math.max(0.5, scale * 0.8), 0, Math.PI * 2);
8961	        ctx.fill();
8962	      }
8963	    }
8964	  }
8965	
8966	  // Roof
8967	  ctx.fillStyle = '#666666';
8968	  ctx.fillRect(x - w * 0.05, y, w * 1.1, roofH * 0.15);
8969	  // Roof slant
8970	  ctx.fillStyle = '#555555';
8971	  ctx.beginPath();
8972	  ctx.moveTo(x - w * 0.08, y + roofH * 0.15);
8973	  ctx.lineTo(sx, y - roofH * 0.15);
8974	  ctx.lineTo(x + w + w * 0.08, y + roofH * 0.15);
8975	  ctx.closePath();
8976	  ctx.fill();
8977	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
8978	  ctx.lineWidth = Math.max(0.5, scale * 0.6);
8979	  ctx.stroke();
8980	
8981	  // Support pillars
8982	  var pillarW = Math.max(2, scale * 3);
8983	  ctx.fillStyle = '#777777';
8984	  ctx.fillRect(x + w * 0.05, y + roofH * 0.1, pillarW, h * 0.5);
8985	  ctx.fillRect(x + w * 0.95 - pillarW, y + roofH * 0.1, pillarW, h * 0.5);
8986	}
