8988	// ---------------------------------------------------------------------------
8989	// R.renderCrowd — draw crowd dots in grandstand
8990	// ---------------------------------------------------------------------------
8991	R.renderCrowd = function (grandstandX, grandstandY) {
8992	  var ctx = R.ctx;
8993	  var cam = R.camera;
8994	  var screen = R.worldToScreen
8995	    ? R.worldToScreen(grandstandX, grandstandY, 0)
8996	    : defaultWorldToScreen(grandstandX, grandstandY, 0, cam.x, cam.y, cam.zoom);
8997	
8998	  if (!screen || !screen.visible) return;
8999	  if (screen.x < -200 || screen.x > R.canvas.width + 200 ||
9000	      screen.y < -200 || screen.y > R.canvas.height + 200) return;
9001	
9002	  // Find main grandstand object for dimensions
9003	  var gs = null;
9004	  for (var i = 0; i < R.sceneryObjects.length; i++) {
9005	    if (R.sceneryObjects[i].type === 'grandstand') {
9006	      gs = R.sceneryObjects[i];
9007	      break;
9008	    }
9009	  }
9010	  if (!gs) return;
9011	
9012	  var scale = screen.scale;
9013	  var w = gs.width * scale;
9014	  var h = gs.height * scale;
9015	  var x = screen.x - w * 0.5;
9016	  var y = screen.y - h;
9017	  var roofH = h * 0.45;
9018	  var tiers = 6;
9019	  var tierH = h * 0.55 / tiers;
9020	  var tierOffset = w * 0.03;
9021	  var baseY = y + roofH;
9022	
9023	  // Crowd dots per tier
9024	  for (var t = 0; t < tiers; t++) {
9025	    var tw = w - t * tierOffset * 2;
9026	    var tx = x + t * tierOffset;
9027	    var ty = baseY + t * tierH;
9028	    var peoplePerRow = Math.floor(tw / Math.max(3, 4 * scale));
9029	    if (peoplePerRow < 1) peoplePerRow = 1;
9030	
9031	    // Seed based on tier
9032	    var seed = t * 137 + 42;
9033	
9034	    for (var p = 0; p < peoplePerRow; p++) {
9035	      var px = tx + tw * (p + 0.5) / peoplePerRow;
9036	      var py = ty + tierH * 0.35;
9037	      // Skip some seats for natural look
9038	      if (((seed + p * 11) % 7) === 0) continue;
9039	
9040	      // Small person dot
9041	      var skin = SKIN_TONES[(seed + p * 3) % SKIN_TONES.length];
9042	      var shirt = SHIRT_COLORS[(seed + p * 7) % SHIRT_COLORS.length];
9043	      var dotR = Math.max(1.2, scale * 1.8);
9044	
9045	      // Head
9046	      ctx.fillStyle = skin;
9047	      ctx.beginPath();
9048	      ctx.arc(px, py - dotR * 0.4, dotR * 0.6, 0, Math.PI * 2);
9049	      ctx.fill();
9050	
9051	      // Body
9052	      ctx.fillStyle = shirt;
9053	      ctx.fillRect(px - dotR * 0.4, py, dotR * 0.8, dotR * 0.9);
9054	    }
9055	  }
9056	};
