9058	// ---------------------------------------------------------------------------
9059	// Helper: shade a hex color darker or lighter
9060	// ---------------------------------------------------------------------------
9061	function shadeColor(color, percent) {
9062	  var num = parseInt(color.replace('#', ''), 16);
9063	  var amt = Math.round(2.55 * percent);
9064	  var R = (num >> 16) + amt;
9065	  var G = ((num >> 8) & 0x00ff) + amt;
9066	  var B = (num & 0x0000ff) + amt;
9067	  R = R < 0 ? 0 : R > 255 ? 255 : R;
9068	  G = G < 0 ? 0 : G > 255 ? 255 : G;
9069	  B = B < 0 ? 0 : B > 255 ? 255 : B;
9070	  return '#' + (0x1000000 + R * 0x10000 + G * 0x100 + B).toString(16).slice(1);
9071	}
