9073	// ---------------------------------------------------------------------------
9074	// Helper: default world-to-screen projection (fallback if R.worldToScreen is
9075	// not yet defined). Uses simple perspective projection with camera offset.
9076	// ---------------------------------------------------------------------------
9077	function defaultWorldToScreen(wx, wy, wz, camX, camY, zoom) {
9078	  var canvasW = R.canvas.width;
9079	  var canvasH = R.canvas.height;
9080	  var cx = canvasW * 0.5;
9081	  var cy = canvasH * 0.4; // horizon line
9082	
9083	  // World offset relative to camera
9084	  var rx = wx - camX;
9085	  var ry = wy - camY;
9086	  var rz = wz; // elevation
9087	
9088	  // Simple perspective: farther objects appear higher and smaller
9089	  var perspectiveFactor = 1;
9090	  if (ry > 1) {
9091	    perspectiveFactor = 300 / ry;
9092	  } else {
9093	    perspectiveFactor = 1;
9094	  }
9095	
9096	  var scale = perspectiveFactor * zoom;
9097	  var sx = cx + rx * perspectiveFactor * zoom;
9098	  var sy = cy - rz * perspectiveFactor * zoom + perspectiveFactor * zoom * 50;
9099	
9100	  // Visibility check
9101	  var visible = perspectiveFactor > 0.01 && perspectiveFactor < 2.0;
9102	  if (ry <= 0) visible = false;
9103	
9104	  return { x: sx, y: sy, scale: scale, visible: visible };
9105	}
